# Load the required packages
library(pheatmap)
library(grDevices) 

# 1. Import the distance matrix generated by snp-dists
snp_dist <- read.csv("snp_matrix_no_outgroup.csv", row.names = 1, check.names = FALSE)
snp_mat <- as.matrix(snp_dist)

# 2. Color gradient (dark red -> light color -> dark blue)
# Create a 100-color gradient using the selected HEX color codes
my_colors <- colorRampPalette(c("#6A0624", "#FDD2BC", "#053061"))(100)

# 3. Plot the clustered heatmap
pheatmap(snp_mat,
         clustering_distance_rows = "euclidean",
         clustering_distance_cols = "euclidean",
         clustering_method = "complete",
         color = my_colors,             
         border_color = "grey60",        
         display_numbers = FALSE)
